import {
  MainWrapper,
  ContentWrapper,
  ProjectModule,
  Image,
  ProjectContentWrapper,
  Button,
  Descriptor,
OtherWrapper
} from "./index.stitches";
import data from "../../data/project.json";
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome'
import { faArrowRight} from '@fortawesome/free-solid-svg-icons'

function ProjectGrid() {
  return (
    <MainWrapper>
      <ContentWrapper>
        {data.map((item, i) => {
          return (
            <ProjectModule key={i}>
              <Image />
              <ProjectContentWrapper>
                <p>{i + 1}/{data.length}</p>
                <h3>{item[0]}</h3>
                <Button href={''}>
                    <p>Link to story</p>
                    <FontAwesomeIcon icon={faArrowRight}/>
                    </Button>
                <Descriptor><span>{item[2] + ' |'}</span>{' ' + item[3]}</Descriptor>
              </ProjectContentWrapper>
            </ProjectModule>
          );
        })}
        <OtherWrapper>
            <h3>Other Work</h3>
        </OtherWrapper>
      </ContentWrapper>
    </MainWrapper>
  );
}

export default ProjectGrid;
